<?php
declare(strict_types=1);
final class AdminRepositoryModel
{
 public function listing(string $filter='',array $pagination=[]):array{$where="p.deleted_at IS NULL AND p.status IN ('approved','defense','published')";$params=[];if(in_array($filter,['eligible','published','incomplete'],true)){if($filter==='published')$where.=" AND p.status='published'";elseif($filter==='eligible')$where.=" AND p.status IN ('approved','defense') AND EXISTS(SELECT 1 FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL)";else $where.=" AND p.status IN ('approved','defense') AND NOT EXISTS(SELECT 1 FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL)";}$from=" FROM projects p JOIN project_types pt ON pt.id=p.project_type_id JOIN careers c ON c.id=p.career_id JOIN academic_periods ap ON ap.id=p.academic_period_id LEFT JOIN users u ON u.id=p.tutor_id WHERE $where";$sql="SELECT p.id,p.code,p.title,p.summary,p.status,p.published_at,p.updated_at,pt.name type_name,c.name career_name,ap.name period_name,u.full_name tutor_name,(SELECT COUNT(*) FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL) file_count,(SELECT GROUP_CONCAT(DISTINCT UPPER(f.extension) ORDER BY f.extension SEPARATOR ', ') FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL) formats".$from.' ORDER BY COALESCE(p.published_at,p.updated_at) DESC';return PaginationService::run(Database::connection(),'SELECT COUNT(*)'.$from,$sql,$params,$pagination?:PaginationService::request());}
 public function summary():array{$d=Database::connection();return ['eligible'=>(int)$d->query("SELECT COUNT(*) FROM projects p WHERE p.deleted_at IS NULL AND p.status IN ('approved','defense') AND EXISTS(SELECT 1 FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL)")->fetchColumn(),'published'=>(int)$d->query("SELECT COUNT(*) FROM projects WHERE deleted_at IS NULL AND status='published'")->fetchColumn(),'incomplete'=>(int)$d->query("SELECT COUNT(*) FROM projects p WHERE p.deleted_at IS NULL AND p.status IN ('approved','defense') AND NOT EXISTS(SELECT 1 FROM project_files f WHERE f.project_id=p.id AND f.deleted_at IS NULL)")->fetchColumn()];}
 public function setPublished(int $id,bool $publish,int $actor):void{if($id<1)throw new InvalidArgumentException('El proyecto no es válido.');Database::transaction(function(PDO $d)use($id,$publish,$actor):void{$q=$d->prepare('SELECT p.id,p.title,p.status,p.published_at,pt.code type_code FROM projects p JOIN project_types pt ON pt.id=p.project_type_id WHERE p.id=:id AND p.deleted_at IS NULL FOR UPDATE');$q->execute(['id'=>$id]);$before=$q->fetch();if(!$before)throw new InvalidArgumentException('El proyecto ya no está disponible.');if($publish){$required=$before['type_code']==='thesis'?'defense':'approved';if($before['status']!==$required)throw new InvalidArgumentException($required==='defense'?'La tesis debe encontrarse En tribunal antes de publicarse.':'El proyecto debe estar aprobado antes de publicarse.');$files=$d->prepare('SELECT COUNT(*) FROM project_files WHERE project_id=:id AND deleted_at IS NULL');$files->execute(['id'=>$id]);if((int)$files->fetchColumn()<1)throw new InvalidArgumentException('Agrega al menos un documento final antes de publicar.');$d->prepare("UPDATE projects SET status='published',published_at=CURRENT_TIMESTAMP WHERE id=:id")->execute(['id'=>$id]);$after=['status'=>'published'];$action='project_published';}else{if($before['status']!=='published')throw new InvalidArgumentException('El proyecto no está publicado.');$previous=$before['type_code']==='thesis'?'defense':'approved';$d->prepare('UPDATE projects SET status=:status,published_at=NULL WHERE id=:id')->execute(['status'=>$previous,'id'=>$id]);$after=['status'=>$previous];$action='project_unpublished';}(new ProjectAuditService($d))->record($id,$actor,$action,'project',$id,$before,$after);});}
}
